/*
# Seed Categories and Menu Items

## Overview
Inserts all 9 menu categories and all menu items from the VERO VITO menu specification.
No prices, no images — both are added later via the Admin Dashboard.

## Categories inserted (in order):
1. Fresh Cut Fruits
2. Avocado Cocktails
3. Cocktails & Fresh Juices
4. Iced Coffee
5. Milkshake
6. Mojitos
7. Coffee & Hot Drinks
8. Breakfast and Bowls
9. Desserts

## Menu Items
All items from the specification are inserted with English and Arabic names/descriptions.
Where the spec only provided English, the Arabic name matches the English name (transliteration
or direct translation), and description_ar is the same as description_en where no Arabic was provided.
*/

-- ============ CATEGORIES ============
ON CONFLICT DO NOTHING;

-- Helper: get category IDs
DO $$
DECLARE
  cat_fruits uuid; cat_avocado uuid; cat_cocktails uuid; cat_iced uuid;
  cat_milkshake uuid; cat_mojitos uuid; cat_coffee uuid; cat_breakfast uuid; cat_desserts uuid;
BEGIN
  SELECT id INTO cat_fruits FROM categories WHERE name_en = 'Fresh Cut Fruits';
  SELECT id INTO cat_avocado FROM categories WHERE name_en = 'Avocado Cocktails';
  SELECT id INTO cat_cocktails FROM categories WHERE name_en = 'Cocktails & Fresh Juices';
  SELECT id INTO cat_iced FROM categories WHERE name_en = 'Iced Coffee';
  SELECT id INTO cat_milkshake FROM categories WHERE name_en = 'Milkshake';
  SELECT id INTO cat_mojitos FROM categories WHERE name_en = 'Mojitos';
  SELECT id INTO cat_coffee FROM categories WHERE name_en = 'Coffee & Hot Drinks';
  SELECT id INTO cat_breakfast FROM categories WHERE name_en = 'Breakfast and Bowls';
  SELECT id INTO cat_desserts FROM categories WHERE name_en = 'Desserts';

  -- ============ FRESH CUT FRUITS ============

  -- ============ AVOCADO COCKTAILS ============

  -- ============ COCKTAILS & FRESH JUICES ============

  -- ============ ICED COFFEE ============

  -- ============ MILKSHAKE ============

  -- ============ MOJITOS ============

  -- ============ COFFEE & HOT DRINKS ============

  -- ============ BREAKFAST AND BOWLS ============

  -- ============ DESSERTS ============
END $$;